/* ------------------------------------------------------------ card --- */

/**
 * What the app's ThemeProvider puts on <html> for the default theme in
 * semi-transparent mode, in the desktop app: the scene root carries the same
 * attributes so the app's own stylesheet (app.css) resolves as it does there.
 */
export const SCENE_ROOT = {
  "data-appearance": "dark",
  "data-transparency": "on",
  "data-grayscale": "off",
  "data-text-visibility": "off",
  "data-native": "true",
  "data-space": "10",
} as const;

/** A product card: the scene's wallpaper plus the scene laid out at `width` x `height`. */
export function Shot({
  id,
  width,
  height,
  className = "",
  children,
}: {
  /** The scene, which also picks its wallpaper. */
  id: BackdropScene;
  width: number;
  height: number;
  className?: string;
  children: ReactNode;
}) {
  return (
    // data-nosnippet: the scene's terminal text is sample output, so search
    // results quote the page's own copy instead.
    <div className={`h-visual ${className}`} data-nosnippet="">
      <Backdrop scene={id} />
      <Stage width={width} height={height}>
        <div className="pz" {...SCENE_ROOT} style={{ position: "absolute", inset: 0 }}>
          {children}
        </div>
      </Stage>
    </div>
  );
}

